alter table private.quiz_content
  drop constraint quiz_content_rights_status;

alter table private.quiz_content
  add constraint quiz_content_rights_status check (
    rights_status in (
      'public_domain_national_symbol',
      'trademark_review_required',
      'trademark_reviewed_approved',
      'wikimedia_commons_licensed'
    )
  );

on conflict (id) do update set
  display_name = excluded.display_name,
  is_active = excluded.is_active,
  current_content_version = excluded.current_content_version;

-- GENERATED_BRAND_CONTENT_START
on conflict (content_version, item_id) do update set
  display_name = excluded.display_name, asset_path = excluded.asset_path, reveal_asset_path = excluded.reveal_asset_path,
  asset_sha256 = excluded.asset_sha256, source_page_url = excluded.source_page_url, source_asset_url = excluded.source_asset_url,
  rights_status = excluded.rights_status, attribution = excluded.attribution, difficulty = excluded.difficulty, metadata = excluded.metadata;
-- GENERATED_BRAND_CONTENT_END

-- GENERATED_PEOPLE_CONTENT_START
on conflict (content_version, item_id) do update set
  display_name = excluded.display_name, asset_path = excluded.asset_path, reveal_asset_path = excluded.reveal_asset_path,
  asset_sha256 = excluded.asset_sha256, source_page_url = excluded.source_page_url, source_asset_url = excluded.source_asset_url,
  rights_status = excluded.rights_status, attribution = excluded.attribution, difficulty = excluded.difficulty, metadata = excluded.metadata;
-- GENERATED_PEOPLE_CONTENT_END
